+// RF-004: descuento por línea en porcentaje entero 0-100 (ausente = 0), aplicado antes del total
+// y redondeado al centavo. Todo en centavos enteros (ADR-001).
+export function totalLineaCentavos(item) {
+  const descuento = item.descuentoPorcentaje === undefined ? 0 : item.descuentoPorcentaje;
+  if (!Number.isInteger(descuento) || descuento < 0 || descuento > 100)
+    throw new RangeError("Descuento inválido: debe ser un entero de 0 a 100");
+  const bruto = item.cantidad * item.precioUnitarioCentavos;
+  return bruto - Math.round((bruto * descuento) / 100);
+}
