diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..c5f2e3d 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,41 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+test("RF-004: descuento por línea en porcentaje entero 0-100, aplicado antes del total", () => {
+  const f = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 }]);
+  assert.deepEqual(f, { totalCentavos: 1800, ivaCentavos: 234, netoCentavos: 1566 });
+});
+
+test("RF-004: sin descuento indicado, la línea cuesta el precio completo", () => {
+  const f = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 0 }]);
+  assert.equal(f.totalCentavos, 2000);
+  assert.equal(calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000 }]).totalCentavos, 2000);
+});
+
+test("RF-004: el descuento se redondea al centavo", () => {
+  // 1 × 10,01 Bs con 10 %: descuento 1,001 Bs -> 1,00 Bs; total 9,01 Bs
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1001, descuentoPorcentaje: 10 }]).totalCentavos, 901);
+  // 3 × 3,33 Bs con 33 %: descuento 3,2967 Bs -> 3,30 Bs; total 6,69 Bs
+  assert.equal(calcularFactura([{ cantidad: 3, precioUnitarioCentavos: 333, descuentoPorcentaje: 33 }]).totalCentavos, 669);
+});
+
+test("RF-004: un descuento fuera de 0-100, no entero o no numérico se rechaza", () => {
+  for (const descuentoPorcentaje of [-1, 101, 10.5, "10", null]) {
+    assert.throws(
+      () => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje }]),
+      RangeError,
+      `debería rechazar ${descuentoPorcentaje}`,
+    );
+  }
+});
+
+test("RF-004: el descuento queda registrado en la línea de la factura emitida congelada", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: [{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 }] });
+  assert.equal(f.totalCentavos, 1800);
+  assert.equal(f.items[0].descuentoPorcentaje, 10);
+  assert.ok(Object.isFrozen(f.items[0]));
+});
